exercises.solution:
const stages = [
  { name: 'build', ok: true },
  { name: 'test', ok: false },
  { name: 'deploy', ok: true }
];
for (const stage of stages) {
  console.log('running ' + stage.name);
  if (!stage.ok) {
    console.log('STOPPED at ' + stage.name);
    break;
  }
}

